package com.sodi.metareports.user; import com.sodi.metareports.audit.AuditService; import com.sodi.metareports.role.repository.RoleRepository; import com.sodi.metareports.user.dto.UserForm; import com.sodi.metareports.user.entity.AppUser; import com.sodi.metareports.user.repository.AppUserRepository; import java.time.Instant; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class UserAdminService { private final AppUserRepository users; private final RoleRepository roles; private final PasswordEncoder encoder; private final AuditService audit; private final int passwordMinLength; public UserAdminService(AppUserRepository u,RoleRepository r,PasswordEncoder e,AuditService a,@Value("${app.security.password-min-length:12}") int min){users=u;roles=r;encoder=e;audit=a;passwordMinLength=min;}
 @Transactional public AppUser create(UserForm f){if(users.findByUsernameIgnoreCase(f.getUsername()).isPresent()||users.existsByEmailIgnoreCase(f.getEmail()))throw new DataIntegrityViolationException("Username or email already exists");AppUser u=new AppUser();apply(u,f);validatePassword(f.getPassword());u.setPasswordHash(encoder.encode(f.getPassword()));u.setPasswordChangedAt(Instant.now());AppUser saved=users.save(u);audit.record("USER_CREATE","User",saved.getId().toString(),"User created",null,Map.of("username",saved.getUsername()));return saved;}
 @Transactional public void toggle(UUID id){AppUser u=get(id);u.setEnabled(!u.isEnabled());audit.record("USER_STATUS","User",id.toString(),"User enabled state changed",null,Map.of("enabled",u.isEnabled()));}
 @Transactional public void unlock(UUID id){AppUser u=get(id);u.setAccountLocked(false);u.setLockedUntil(null);u.setFailedLoginAttempts(0);audit.record("USER_UNLOCK","User",id.toString(),"User unlocked",null,null);}
 @Transactional public void password(UUID id,String value){validatePassword(value);AppUser u=get(id);u.setPasswordHash(encoder.encode(value));u.setPasswordChangedAt(Instant.now());audit.record("USER_PASSWORD_CHANGE","User",id.toString(),"Administrative password change",null,null);}
 public AppUser get(UUID id){return users.findById(id).orElseThrow();} private void apply(AppUser u,UserForm f){u.setUsername(f.getUsername().trim().toLowerCase());u.setEmail(f.getEmail().trim().toLowerCase());u.setFirstName(f.getFirstName().trim());u.setLastName(f.getLastName().trim());u.setRoles(new HashSet<>(roles.findAll().stream().filter(r->f.getRoleCodes().contains(r.getCode())).toList()));} private void validatePassword(String value){if(value==null||value.length()<passwordMinLength)throw new IllegalArgumentException("Password does not meet the configured minimum length");}}
